#!/usr/bin/env python3
"""Batch 57 — Generational sections polish (25 entries from 50-90w bucket).

Clears most of the remaining thin entries across all four generational
decoded sections. Pushes the slang reframes uniformly to the deep tier.
"""
import os, re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DICT_DIR = os.path.join(ROOT, 'docs', 'dictionary')

EXPANSIONS = {
    'catch-you-on-flip-side': (
        '<p>"Catch you on the flip side" is the Boomer-era casual farewell — drawn from vinyl-record vocabulary (the B-side of a 45-rpm single, the "flip side") and roughly meaning <em>"I’ll see you later."</em> Era-stamped 1960s-70s mainstream now nostalgic. The slang’s image — literally <em>"the other side"</em> — resonates oddly with Christian eschatology, where the farewells of this age give way to the great reunion on the other side of the resurrection. <em>"For now we see through a glass, darkly; but then face to face: now I know in part; but then shall I know even as also I am known"</em> (<em>1 Corinthians 13:12</em>). The Boomer slang traffics innocently in the imagery of B-sides; Christian farewell holds the substance — every parting between saints is provisional until the final reunion.</p>'
    ),
    'millennial-pause': (
        '<p>The "Millennial pause" is the brief silent pause at the start of a video clip that Millennials leave from habits formed in the early-2010s era of less-reliable mobile recording — when one had to wait to confirm the camera was actually rolling before speaking. Gen-Z, who grew up with auto-start cameras and always-recording defaults, identified and mocked the pause as a generational tell. The Christian observation is small but real: every generation’s habits are formed by the technology it learned on, and habits outlast the conditions that produced them. <em>"To every thing there is a season, and a time to every purpose under the heaven"</em> (<em>Ecclesiastes 3:1</em>). Christian men should occasionally audit their own habits — including the involuntary ones — for whether they still serve, or have become merely vestigial signatures of an earlier era.</p>'
    ),
    'totes': (
        '<p>"Totes" is the casual Millennial abbreviation of <em>"totally"</em> — part of the cute-abbreviation family (<em>"adorbs," "obvi," "cray," "presh," "amazeballs"</em>) that emerged in 2010s Millennial speech and TV writing (Tina Fey, <em>30 Rock</em>). Theologically neutral as a single word; the pattern points at something worth examining. The cute-abbreviation cluster reveals a generational preference for the playful, ironic, and infantilized over the direct, weighty, and adult. Scripture commends precise speech: <em>"A word fitly spoken is like apples of gold in pictures of silver"</em> (<em>Proverbs 25:11</em>); <em>"Let your speech be alway with grace, seasoned with salt"</em> (<em>Colossians 4:6</em>). Christian men should be able to deploy the slang when fitting and step into weighty plain speech when needed. The vocabulary should serve the speaker, not infantilize him.</p>'
    ),
    'chillax': (
        '<p>"Chillax" is the Gen-X slang command — a portmanteau of <em>chill</em> and <em>relax</em> — typically delivered to someone judged to be over-intense, anxious, or angry. The slang names something real: some intensity <em>is</em> misplaced and needs to be released. <em>"Be not righteous over much; neither make thyself over wise: why shouldest thou destroy thyself?"</em> (<em>Ecclesiastes 7:16</em>); <em>"Cast thy burden upon the LORD, and he shall sustain thee"</em> (<em>Psalm 55:22</em>). But the slang as habitual instruction can also become a license for spiritual laxity — telling someone to "chillax" about sin, about gospel-clarity, about ultimate things. Some intensity is exactly right. Christ overturned the moneychangers’ tables; Paul withstood Peter to the face. Discernment names <em>which</em> intensity must be released and <em>which</em> intensity must be defended.</p>'
    ),
    'on-god': (
        '<p>"On God" is the Gen-Z casual verbal oath — swearing on God’s name to emphasize a claim’s truth (<em>"that was crazy, on God"</em>). The slang treats it as mere intensifier; Scripture treats oaths as serious covenantal acts. Christ explicitly warned against casual oath-taking: <em>"Swear not at all; neither by heaven... nor by the earth... Neither shalt thou swear by thy head... But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil"</em> (<em>Matthew 5:34-37; James 5:12</em>). The third commandment forbids taking the LORD’s name in vain (<em>Exodus 20:7</em>). Christian men should refuse the slang directly. If your word as a Christian man is reliable, no oath should be needed to confirm it. If your word is unreliable, no oath actually confirms it.</p>'
    ),
    'doggo': (
        '<p>"Doggo" is the affectionate playful renaming of <em>dog</em> — part of the broader Millennial pattern called <em>"DoggoLingo"</em> (<em>"pupper, floof, boopable snoot, woofer"</em>) that treats pets as small humans expressed in baby-talk vocabulary, social-media presence, premium consumer products, and parental affection. The Christian observation is sober. Scripture values animals as God’s creatures (<em>Proverbs 12:10</em>: <em>"a righteous man regardeth the life of his beast"</em>) — but never sentimentally inverts the creation order. Pets are <em>not</em> human, are <em>not</em> children, and are <em>not</em> spouses. A culture that calls dogs <em>"fur babies"</em> and forgoes actual human children for them has confused God’s order. <em>"Be fruitful, and multiply, and replenish the earth"</em> (<em>Genesis 1:28</em>). Love the doggo; have the children.</p>'
    ),
    'dynamite': (
        '<p>"Dynamite" is the Boomer-era superlative meaning <em>"excellent, awesome, top-tier."</em> Peaked in the 1970s; permanently associated with J. J. Evans’s catchphrase on the sitcom <em>Good Times</em> (1974-79). The same category as other generational superlatives (<em>"groovy, far out, the bomb, lit, fire, sick"</em>) — every generation reinvents the word for "very good." Christ’s observation behind the slang holds across eras: <em>"For where your treasure is, there will your heart be also"</em> (<em>Matthew 6:21</em>). What a man habitually calls <em>dynamite</em> reveals his hierarchy of value. If the dynamite-labels stack on food, entertainment, gear, and sports and never on Scripture, prayer, the saints, or the gospel, the audit is uncomfortable but useful. Reorder the superlatives.</p>'
    ),
    'cowabunga': (
        '<p>"Cowabunga" is the era-stamped exclamation of excitement or readiness for action. Surfer / skateboarder origin in the 1950s-60s; mainstreamed in 1980s pop culture by the Teenage Mutant Ninja Turtles and earlier by <em>Howdy Doody</em>. The slang is purely expressive — like Boomer <em>"far out"</em> or modern <em>"let’s go!"</em> — a verbal trigger for shared enthusiasm. The Christian observation: shared exclamations of joy are a normal part of community life. The Psalms are full of communal shouting: <em>"Make a joyful noise unto the LORD, all the earth: make a loud noise, and rejoice, and sing praise"</em> (<em>Psalm 98:4</em>). Christian celebration should not be muted by misplaced reverence. The same lungs that shouted <em>"cowabunga"</em> at the skate park can shout <em>"hallelujah"</em> in worship. Use them.</p>'
    ),
    'pad-place': (
        '<p>"Pad" is the Boomer-era casual term for one’s home or apartment — drawn from jazz, beat-poet, and hippie vocabulary of the mid-twentieth century (<em>"my pad," "crash at my pad," "swinging pad"</em>). The slang names something theologically modest: home is just a place to be. The Christian observation: Scripture treats the household with far more weight. The home is the small church (<em>"the church... in thy house"</em>, <em>Philemon 2</em>; <em>Romans 16:5</em>); the household altar (<em>"as for me and my house, we will serve the LORD"</em>, <em>Joshua 24:15</em>); the place of hospitality to strangers (<em>Hebrews 13:2</em>); the workshop where children are catechized (<em>Deuteronomy 6:7</em>); the proving ground of a man’s pastoral fitness (<em>1 Timothy 3:4-5</em>). Don’t just have a pad; build a household.</p>'
    ),
    'looksmaxxing': (
        '<p>"Looksmaxxing" is the disciplined, often obsessive optimization of personal appearance — gym, skincare, mewing, hair, fashion, cosmetic procedures — popular in Gen-Z male-aesthetics communities online. The category is honest about its goal: maximum attractiveness as the dominant project of identity-formation. The Christian critique runs deep. Scripture treats bodily care as good and stewardly (<em>1 Corinthians 6:19-20</em>) but absolutely refuses to make appearance the soul’s measure: <em>"the LORD seeth not as man seeth; for man looketh on the outward appearance, but the LORD looketh on the heart"</em> (<em>1 Samuel 16:7</em>); <em>"Favour is deceitful, and beauty is vain: but a woman that feareth the LORD, she shall be praised"</em> (<em>Proverbs 31:30</em>). Looksmaxxing makes the body an idol. The Christian man trains the body and feeds the soul; he does not invert the order.</p>'
    ),
    'nope': (
        '<p>"Nope" is the Millennial-era conversational refusal-marker — long-standing American casual <em>"no,"</em> but Millennial usage has given it added weight. <em>"Nope"</em> often signals not just disagreement but a refusal to engage further — <em>"I will not be persuaded; this conversation is closed."</em> The deeper Christian concern is the broader social pattern: tone-policed dismissal as the new way to win an argument without arguing. Scripture commands plain refusal where required — <em>"Let your communication be, Yea, yea; Nay, nay"</em> (<em>Matthew 5:37</em>) — but never as a kill-switch on legitimate engagement. The Bereans <em>"received the word with all readiness of mind, and searched the scriptures daily, whether those things were so"</em> (<em>Acts 17:11</em>). Christian men hold firm convictions <em>and</em> remain open to correction by Scripture. <em>"Nope"</em> shuts both doors.</p>'
    ),
    'booyah': (
        '<p>"Booyah" is the Gen-X-era celebratory exclamation — triumph, victory, satisfaction after a successful action. Era-stamped; permanently associated with ESPN <em>SportsCenter</em> anchor Stuart Scott (1965-2015), who deployed it after great athletic plays. The Christian observation: the slang names a real category — Scripture commends celebration after victory. David danced before the ark <em>"with all his might"</em> (<em>2 Samuel 6:14</em>). Miriam led the women in the song of the sea after the Red Sea (<em>Exodus 15:20-21</em>). The redeemed multitude in <em>Revelation 19:1-6</em> sings <em>"Alleluia"</em> with a voice as the sound of many waters. Christian victory cries are appropriate and good. Just make sure the victories celebrated are actually worth celebrating — and that the LORD gets the credit. <em>"Not unto us, O LORD, not unto us, but unto thy name give glory"</em> (<em>Psalm 115:1</em>).</p>'
    ),
    'bell-bottoms': (
        '<p>"Bell-bottoms" are the 1960s-70s Boomer fashion marker — trousers flared widely from the knee down. Originally a U.S. Navy uniform (the wide cuffs allowed sailors to roll the legs up for deck work), adopted by hippie counterculture as anti-establishment style, mainstreamed through the 1970s, retired in the 1980s, and revived in cycles since. The Christian observation: fashion is a small but real social signal. Scripture does not prescribe trouser widths but does command modesty (<em>1 Timothy 2:9</em>; <em>1 Peter 3:3-4</em>) and sex-distinct dress (<em>Deuteronomy 22:5</em>). Christian men and women should dress in ways that honor their sex, their household, their station, and their generation — without slavish conformity to changing fashion or principled rejection of all fashion. Old bell-bottoms in the closet are harmless; the soul’s vanity is not.</p>'
    ),
    'ohio': (
        '<p>"Ohio" is the Gen-Alpha / Gen-Z slang use of the state name as a generic descriptor for the weird, chaotic, or absurd (<em>"that’s so Ohio"</em>). A meme-coded vocabulary marker, originating in viral TikTok and Skibidi-era humor, with no real connection to the actual state. The Christian observation: harmless slang in itself; the deeper category is generational shibboleths — words whose meaning is only legible to in-group members and which serve to mark belonging to the cohort. Every generation has them. Christian men can use them without anxiety when speaking to their generation, but should not assume they translate. <em>"I am made all things to all men, that I might by all means save some"</em> (<em>1 Corinthians 9:22</em>). Speak the dialect your hearers actually speak; remember that the gospel must always be the substance underneath.</p>'
    ),
    'avocado-toast': (
        '<p>"Avocado toast" is the cultural shorthand for the Millennial generation’s spending habits as critiqued by Boomers — specifically, an Australian property developer’s 2017 viral interview claim that Millennials could not buy homes because they were spending their money on $19 avocado toast and luxury coffee. The 2017 controversy crystallized a generational dispute: are Millennials priced out of homeownership by structural housing costs and stagnant wages, or by their own spending priorities? The honest Christian answer takes both seriously. Structural injustice exists; personal stewardship also exists. Scripture commands both honesty in economic systems (<em>Amos 5; James 5:1-6</em>) and personal frugality (<em>"He becometh poor that dealeth with a slack hand"</em>, <em>Proverbs 10:4</em>). Christian young men: build wealth slowly, give generously, and own your own choices.</p>'
    ),
    'easy-peasy': (
        '<p>"Easy-peasy" is the mid-twentieth-century children’s reduplicative phrase for very easy — Boomer-era mainstream, now somewhat era-stamped. The slang is purely expressive. The Christian observation: the category of <em>easy</em> in Christian life is biblical but specific. Christ promises: <em>"Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light"</em> (<em>Matthew 11:29-30</em>). Yet He also commands cross-bearing (<em>Luke 9:23</em>), counting the cost (<em>14:28</em>), enduring to the end (<em>Matthew 24:13</em>). Christianity is therefore not easy-peasy in the world’s sense — but the Christian life with Christ’s yoke <em>is</em> easier than life without Him under sin’s yoke. Easy is the right word, in the right place.</p>'
    ),
    'skibidi': (
        '<p>"Skibidi" is the versatile near-meaningless Gen-Alpha slang intensifier originating from the 2023 viral YouTube series <em>Skibidi Toilet</em>. The word does not have a stable meaning; it functions as a generational identity-marker, a verbal in-group signal, and an all-purpose intensifier (<em>"skibidi rizz," "skibidi sigma," "very skibidi"</em>) — used most heavily by children born after 2010. The Christian observation: every generation invents linguistic toys that puzzle the previous generation. Christian parents and grandparents should not panic at the vocabulary; they should pay attention to the <em>content</em> of what is being consumed underneath it. The Skibidi Toilet videos themselves are mostly silly; the larger algorithmic media environment that produced and amplified them is the real concern. Watch the content; the vocabulary will sort itself out.</p>'
    ),
    'influencer': (
        '<p>"Influencer" names a person whose <em>vocation</em> is the cultivation and monetization of personal influence through social-media content. The category is genuinely new — no historical parallel quite matches it. The closest predecessors are celebrity endorsements, fashion-magazine models, and product spokespeople, but the influencer is something distinctive: an ordinary person who has built parasocial intimacy with strangers and converts that intimacy into commerce. The Christian observation is sober. Scripture knows influence by name — pastors, teachers, parents, elders, mentors all wield it (<em>1 Corinthians 4:15-16; Hebrews 13:7</em>) — but always under embodied covenant relationship and accountable to God. Influencer-influence is disembodied, parasocial, and unaccountable. Christian "influencers" who do not also belong to a local church under elder oversight are dangerous to themselves and their audience.</p>'
    ),
    'bingeable': (
        '<p>"Bingeable" is the streaming-era Millennial adjective for content engineered to be consumed in long uninterrupted sessions — cliffhanger structure, addictive plot devices, auto-play timing, recap-skip features, dopamine-tuned editing. The slang celebrates what the business model has engineered for, and the engineering is increasingly sophisticated. The Christian observation: the body and soul God made cannot sustain unbroken consumption of any rich content — even spiritual content — without lasting damage. Scripture commands sabbath-rest from work and pleasure alike (<em>Exodus 20:8-11</em>); Christ Himself withdrew from the crowds repeatedly (<em>Luke 5:16</em>); Paul commanded the church to <em>"redeem the time, because the days are evil"</em> (<em>Ephesians 5:16</em>). A bingeable show eats the hours that should have fed prayer, conversation, sleep, and family. Refuse the engineering. Set the timer.</p>'
    ),
    'beast-mode': (
        '<p>"Beast mode" is the sports-and-gym slang for a state of maximum performance intensity — total focus, total effort, total commitment. Drawn from Marshawn Lynch’s nickname (NFL running back, c. 2009) and amplified through gym culture, video games, and motivational social media. The slang celebrates a real category Scripture also commends: total engagement of strength in the service of a worthy goal. <em>"Whatsoever thy hand findeth to do, do it with thy might"</em> (<em>Ecclesiastes 9:10</em>); <em>"And whatsoever ye do, do it heartily, as to the Lord, and not unto men"</em> (<em>Colossians 3:23</em>); <em>"Quit you like men, be strong"</em> (<em>1 Corinthians 16:13</em>). The Christian critique is only about <em>direction</em>: beast mode toward fleshly self-display is vain; beast mode toward kingdom-work is exactly the right disposition. Christian men: enter beast mode for the kingdom.</p>'
    ),
    'trash-adj': (
        '<p>"Trash" as adjective is the Millennial-era dismissive declaration that something or someone is worthless (<em>"that movie was trash," "he’s trash"</em>). The slang has two distinct uses that deserve different responses. (1) Of <em>things</em> — movies, products, services — it is ordinary taste-judgment, harmless and often accurate. (2) Of <em>persons</em> — <em>"he’s trash," "she’s trash"</em> — it crosses into contempt-language. Christ’s warning: <em>"Whosoever shall say, Thou fool, shall be in danger of hell fire"</em> (<em>Matthew 5:22</em>). No image-bearer of God is "trash." Sinful, yes; corrupted, yes; under judgment apart from Christ, yes — but never garbage. Christian men should freely critique products and refuse to dehumanize persons. The shift from object-judgment to person-judgment in the same vocabulary is exactly where the slang turns dangerous.</p>'
    ),
    'fanum-tax': (
        '<p>"Fanum tax" is the Gen-Z humor-slang originating from streamer Fanum’s running joke of taking small bites of his friends’ food on camera. The phrase spread beyond its origin to function as in-group humor among Gen-Z and Gen-Alpha for friendly small-scale taking — a brother eating his sister’s fries, a friend grabbing a chip. The Christian observation: small mutual generosity within friendship is good and biblical. Christ Himself shared meals constantly (<em>Luke 7:34</em>); the early church <em>"continuing daily with one accord in the temple, and breaking bread from house to house, did eat their meat with gladness and singleness of heart"</em> (<em>Acts 2:46</em>). The deeper warning is the soul’s instinct to <em>monitor</em> small generosities, especially with siblings. The Christian household should be a place where the "Fanum tax" runs freely both ways. Don’t keep score on chips.</p>'
    ),
    'pookie': (
        '<p>"Pookie" is the term of endearment, revived in Gen-Z TikTok usage as a generic affectionate address for friends, romantic interests, pets, and sometimes strangers in stylized speech. Originally a 1980s-era nickname (Don Cheadle’s character in <em>New Jack City</em>, 1991), revived through a 2023 viral skin-care influencer who addressed her audience as <em>"hi pookie."</em> The Christian observation: endearment-vocabulary in Scripture is precise and ordered. <em>"Beloved," "brethren," "little children," "my son"</em> all carry weight and signal a particular relationship. The slang flattens this — <em>"pookie"</em> can mean girlfriend, sister, dog, or stranger in the same paragraph. Christian men should preserve precise endearment-vocabulary for their wives, children, and brothers in Christ. Calling everyone <em>"pookie"</em> empties the word that should mean something irreplaceable to one person.</p>'
    ),
    'phone-tag': (
        '<p>"Phone tag" is the Gen-X-era slang for the back-and-forth missed-call pattern of pre-mobile communication — leaving a message, then receiving one back, then missing each other again, repeating until eventually connecting. Era-obsolete vocabulary, preserved in the dictionary as a generational marker. The Christian observation: the disappearance of phone tag — replaced by always-on texting, voicemail-skipping habits, and the slow death of the actual phone call — has come at a cost. Real-time voice conversation creates intimacy and accountability that text-threads do not. Pastors who only text their flock are not actually pastoring them. Husbands who only text their wives are not actually leading. Christian men should be willing to make and take phone calls, even when texting feels easier. The voice matters.</p>'
    ),
    'mall-rat': (
        '<p>"Mall rat" is the Gen-X-era slang for a teenager who spent inordinate amounts of time hanging around shopping malls — the era’s preferred unsupervised gathering-place for young people in the 1980s-90s, before the mobile internet collapsed the social function of malls. The slang celebrates what the era treated as harmless adolescent loitering. The Christian observation is sober. Adolescent unsupervised time aggregates into character — and the question is always <em>where</em> the unsupervised time is being spent. Mall-rat hours formed many of a generation’s consumer instincts, mating patterns, and friendship structures. Christian parents should ask the same question of their own children’s unsupervised time today (now mostly on screens): what is being formed in the hours no adult is watching? <em>"Train up a child in the way he should go"</em> (<em>Proverbs 22:6</em>) covers unsupervised hours too.</p>'
    ),
}

BD_RE = re.compile(r'(<div class="biblical-def">)(.*?)(</div>)', re.DOTALL)

def patch(slug, new_inner):
    fp = os.path.join(DICT_DIR, f'{slug}.html')
    if not os.path.exists(fp):
        return False, 'file missing'
    with open(fp, encoding='utf-8') as f:
        html = f.read()
    new_html, n = BD_RE.subn(
        rf'\g<1>\n                {new_inner}\n            \g<3>',
        html, count=1)
    if n == 0:
        return False, 'pattern not matched'
    with open(fp, 'w', encoding='utf-8') as f:
        f.write(new_html)
    return True, 'ok'

def main():
    ok, fail = 0, 0
    for slug, new in EXPANSIONS.items():
        success, reason = patch(slug, new)
        if success:
            ok += 1
        else:
            fail += 1
            print(f'  FAIL {slug}: {reason}')
    print(f'Expanded {ok}/{ok+fail} entries')

if __name__ == '__main__':
    main()
